[{"order":1,"type":"heading","text":"Errors as Values and Wrapping in Go"},{"order":2,"type":"paragraph","text":"Go handles error management differently than many modern object-oriented languages. Instead of throwing exceptions that interrupt the normal control flow, Go treats errors as ordinary return values. This tutorial explores idiomatic error handling, leveraging sentinel errors, and utilizing the error wrapping capabilities introduced in Go 1.13."},{"order":3,"type":"subheading","text":"The Basics: Errors as Values"},{"order":4,"type":"paragraph","text":"In Go, the built-in 'error' is simply an interface type consisting of a single method: Error() string. Functions typically return an error as their final return value. Callers check whether the error is nil before proceeding."},{"order":5,"type":"code","text":"package main

import (
	"errors"
	"fmt"
)

func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("division by zero")
	}
	return a / b,
}

func main() {
	result, err := divide(10, 0)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println("Result:", result)
}"},{"order":6,"type":"subheading","text":"Sentinel Errors"},{"order":7,"type":"paragraph","text":"Sentinel errors are predefined, package-level error variables that signify a specific, known failure condition. They usually start with the prefix 'Err'."},{"order":8,"type":"code","text":"var ErrNotFound = errors.New("requested record not found")

func findUser(id int) error {
	// Simulating a missing user
	return ErrNotFound
}"},{"order":9,"type":"subheading","text":"Error Wrapping and Context"},{"order":10,"type":"paragraph","text":"Often, you want to add contextual information to an error as it travels up the call stack, without losing the original error. Go 1.13 introduced the '%%w' verb for fmt.Errorf, allowing you to wrap an underlying error."},{"order":11,"type":"code","text":"package main

import (
	"errors"
	"fmt"
	"os"
)

func readConfigFile() error {
	_, err := os.Open("non_existent.conf")
	if err != nil {
		return fmt.Errorf("failed to read config: %w", err)
	}
	return nil
}

func main() {
	err := readConfigFile()
	if err != nil {
		fmt.Println(err)
	}
}"},{"order":12,"type":"subheading","text":"Inspecting Wrapped Errors"},{"order":13,"type":"paragraph","text":"Because errors can be wrapped deeply, direct equality checks (like err == ErrNotFound) might fail. Go provides two helpful functions in the 'errors' standard library package to inspect wrapped chains: 'errors.Is' and 'errors.As'."},{"order":14,"type":"bullet_point","text":"errors.Is(err, target): Checks if any error in the chain matches a specific target sentinel error."},{"order":15,"type":"bullet_point","text":"errors.As(err, target): Finds the first error in the chain that matches a specific type and casts it."},{"order":16,"type":"code","text":"package main

import (
	"errors"
	"fmt"
)

var ErrPermissionDenied = errors.New("permission denied")

func doOperation() error {
	return fmt.Errorf("operation failed: %w", ErrPermissionDenied)
}

func main() {
	err := doOperation()
	if errors.Is(err, ErrPermissionDenied) {
		fmt.Println("Access denied. Please check your credentials.")
	} else if err != nil {
		fmt.Println("Unknown error occurred:", err)
	}
}"},{"order":17,"type":"subheading","text":"Best Practices"},{"order":18,"type":"bullet_point","text":"Always check for errors immediately after the function call that produces them."},{"order":19,"type":"bullet_point","text":"Use fmt.Errorf with the %%w verb when adding context to errors returned by external packages."},{"order":20,"type":"bullet_point","text":"Use errors.Is and errors.As instead of type assertions or equality checks on wrapped errors."}]
